// =====================================================================================
//  SHIFTERS - L5Builder.cs   [LEVEL 5 - TOTAL CHAOS]
//  "Unstable industrial complex" - the finale. Everything is code (regenerated by BuildAll).
//  Layout along +Z (y = walk height):
//    S0  spawn deck (y 0)                         "MELTDOWN IN PROGRESS"
//    S1  void commute: 3 moving platforms (P2 carries a sweeper arm) -> C1 (y 2)
//    S2  laser hall: cycling lasers + electric floors; a turbo-only crumbling catwalk to the
//        LASER OVERRIDE lever that kills the always-on second half -> C2
//    S3  bot arena (y 0.4): two BONK-BOTs; shoot the glass shelf -> barrel drops on the 25 kg
//        dock plate -> bot A goes to sleep; 150 kg latching plate opens the door; holding cell
//        with a release lever on the bot-proof catwalk -> C3
//    S4  counterweight crusher: braked pulley lift; heavy block (+ the Sprinter) in basket B
//        under a crusher, Brute + Brainiac on A, DISPATCH -> A rises to the upper deck (y 3.4) -> C4
//    S5  escape pod (LevelExit, MAX 200 KG via L5PodWeightLimit). Two fit inside; the third takes
//        the maintenance shaft gauntlet (vertical lifts + lasers) from the pit to the ROOF HATCH.
//  Every metric follows LEVELS.md (gaps, plates 25/150, timed hazards, bot arenas + cell + lever).
// =====================================================================================
using System.Collections.Generic;
using UnityEngine;

namespace Shifters
{
    public class L5Builder : ILevelBuilder
    {
        public int LevelIndex => 4;

        // ---- key metrics (public so the solution / tests can use them)
        public const float S2Y = 2f, ArenaY = 0.4f, DeckY = 0.4f, UpperY = 3.4f, PitY = -2.6f, RoofY = 8.3f;
        public const float PodMaxKg = 200f;

        static readonly Color Red = new Color(1f, 0.22f, 0.16f);
        static readonly Color Amber = new Color(1f, 0.55f, 0.12f);
        static readonly Color Cool = new Color(0.45f, 0.75f, 1f);

        LevelBuildContext _ctx;

        public void Build(LevelBuildContext ctx)
        {
            _ctx = ctx;
            BuildS0();
            BuildS1();
            BuildS2();
            BuildS3();
            BuildS4();
            BuildS5();
            BuildWorld();
        }

        // ================================================================== helpers
        static Quaternion Yaw(float y) => Quaternion.Euler(0f, y, 0f);
        /// <summary>Face rotation of a sign readable by someone walking +Z (its face points -Z).</summary>
        static readonly Quaternion FaceSouth = Quaternion.Euler(0f, 180f, 0f);

        /// <summary>EnvKit mounted pieces (Sign, Poster, LightPanel, SparkingPanel...) take the direction the VIEWER looks
        /// (rot*forward points into the wall). This level authors them by the direction their readable / lit face points
        /// (towards the reader, e.g. FaceSouth), so every such rotation goes through here.</summary>
        static Quaternion Face(Quaternion faceRot) => faceRot * Quaternion.Euler(0f, 180f, 0f);

        /// <summary>Sign whose readable face points along rot*forward (FaceSouth = towards a player walking +Z).</summary>
        GameObject Sign(Transform t, Vector3 pos, Quaternion rot, string text, float w, float h, SignStyle style = SignStyle.Info)
            => EnvKit.Sign(t, pos, Face(rot), text, new Vector2(w, h), style);

        /// <summary>Free-standing sign (see Sign) on thin posts hidden behind the panel, down to the floor at floorY.</summary>
        GameObject PostSign(Transform t, Vector3 pos, Quaternion rot, string text, float w, float h, SignStyle style, float floorY, bool twoPosts = false)
        {
            var go = Sign(t, pos, rot, text, w, h, style);
            float bottom = pos.y - h * 0.5f + 0.02f, len = bottom - floorY;
            if (len > 0.05f)
            {
                var behind = rot * Vector3.back * 0.07f;
                var side = rot * Vector3.right * (w * 0.5f - 0.18f);
                for (int i = 0; i < (twoPosts ? 2 : 1); i++)
                {
                    var x = twoPosts ? (i == 0 ? side : -side) : Vector3.zero;
                    Kit.BoxVisual(go.transform, "Post" + i, go.transform.InverseTransformPoint(new Vector3(pos.x, floorY + len * 0.5f, pos.z) + behind + x),
                        new Vector3(0.1f, len, 0.1f), MatKey.MetalDark, 0.01f, Quaternion.Inverse(go.transform.rotation) * rot);
                }
            }
            return go;
        }

        /// <summary>Two horizontal rods holding a banner (centre pos, half width) between hall walls at +-wallX.</summary>
        static void BannerRods(Transform t, Vector3 pos, float halfWidth, float wallX, float behindZ)
        {
            float len = wallX - halfWidth + 0.06f;
            for (int s = -1; s <= 1; s += 2)
                Kit.BoxVisual(t, "BannerRod", new Vector3(pos.x + s * (halfWidth - 0.06f + len * 0.5f), pos.y, pos.z + behindZ), new Vector3(len, 0.08f, 0.08f), MatKey.MetalDark, 0.01f);
        }

        void Floor(Transform t, Vector3 top, Vector3 size, MatKey mat = MatKey.Floor) => EnvKit.Floor(t, top, size, mat, true);

        void Beacon(Transform t, Vector3 pos, bool lights = false) => EnvKit.Decor.WarningBeacon(t, pos, lights);

        /// <summary>Light panel whose lit face points along rot*forward.</summary>
        void Lamp(Transform t, Vector3 pos, Quaternion rot, Color c, bool light, float w = 1.6f, float h = 0.35f, float intensity = 2.5f)
            => EnvKit.LightPanel(t, pos, Face(rot), new Vector2(w, h), c, light, intensity);

        // ================================================================== S0 spawn
        void BuildS0()
        {
            var t = _ctx.Section("S0_Spawn", Vector3.zero);
            Floor(t, new Vector3(0f, 0f, 4f), new Vector3(14f, 1f, 14f), MatKey.Floor);
            _ctx.SetSpawn(new Vector3(0f, 0f, 1f), 0f);
            _ctx.MarkPoint("S0.Dock", new Vector3(0f, 0f, 9.6f));

            // back wall with the big alarm banner
            EnvKit.Wall(t, new Vector3(-7f, 0f, -3.2f), new Vector3(7f, 0f, -3.2f), 5f, 0.4f, MatKey.WallAlt);
            Sign(t, new Vector3(0f, 3.4f, -2.95f), Quaternion.identity, "MELTDOWN IN PROGRESS", 8.5f, 1.3f, SignStyle.Danger);
            Sign(t, new Vector3(0f, 2.1f, -2.95f), Quaternion.identity, "YOUR FINAL SHIFT HAS BEGUN. PROCEED TO THE ESCAPE POD IN AN ORDERLY PANIC", 8.5f, 0.6f, SignStyle.Warning);
            EnvKit.Wall(t, new Vector3(-7.2f, 0f, -3f), new Vector3(-7.2f, 0f, 6f), 3.5f, 0.4f, MatKey.WallAlt);
            EnvKit.Wall(t, new Vector3(7.2f, 0f, -3f), new Vector3(7.2f, 0f, 6f), 3.5f, 0.4f, MatKey.WallAlt);
            Sign(t, new Vector3(-6.95f, 2.2f, 2f), Yaw(90f), "STRUCTURAL INTEGRITY: 3%", 3.6f, 0.8f, SignStyle.Warning);
            Sign(t, new Vector3(6.95f, 2.2f, 2f), Yaw(-90f), "DAYS WITHOUT A SHIFT ACCIDENT: 0", 3.6f, 0.8f, SignStyle.Info);
            EnvKit.Poster(t, new Vector3(-6.95f, 1.6f, -1f), Face(Yaw(90f)), "IN CASE OF EMERGENCY", "PANIC. THEN FILL OUT FORM 27-B.");
            EnvKit.Poster(t, new Vector3(6.95f, 1.6f, -1f), Face(Yaw(-90f)), "PLEASE DO NOT SHIFT THE BLAME", "(OR THE INTERNS)");
            Beacon(t, new Vector3(-6.5f, 3.5f, -2.6f), true);
            Beacon(t, new Vector3(6.5f, 3.5f, -2.6f));
            EnvKit.Decor.SparkingPanel(t, new Vector3(-3.2f, 1.3f, -3.0f), Face(Quaternion.identity));
            EnvKit.Decor.Debris(t, new Vector3(4.5f, 0f, 6.5f), 1.6f, 12, 11);
            EnvKit.Decor.BrokenBeam(t, new Vector3(-5.6f, 0f, 7.5f), Yaw(35f), 3.2f);
            PostSign(t, new Vector3(3.7f, 1.6f, 10.4f), FaceSouth, "EVACUATION ROUTE  >\n(MAYBE)", 2.6f, 1.0f, SignStyle.Arrow, 0f);
            Lamp(t, new Vector3(0f, 4.6f, -2.95f), Quaternion.identity, Red, true, 6f, 0.3f, 2.2f);

            _ctx.Tutorial(new Vector3(0f, 1.5f, 1.5f), new Vector3(12f, 4f, 7f), "l5_meltdown", "TOTAL CHAOS",
                "MELTDOWN IN PROGRESS. Everything here wants your interns Lost. Get all three to the ESCAPE POD - checkpoints save you, Restart Checkpoint is in the pause menu.",
                new[] { "ESC" }, true);
        }

        // ================================================================== S1 moving platforms over the void
        void BuildS1()
        {
            var t = _ctx.Section("S1_Commute", Vector3.zero);
            var p1 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(0f, 0f, 13.2f), null, new[] { Vector3.zero, new Vector3(0f, 0f, 8f) },
                new Vector3(4.5f, 0.4f, 4f), 2.5f, 2.6f, PlatformLoop.PingPong);
            _ctx.Mark("S1.P1", p1.gameObject);

            EnvKit.Platform(t, new Vector3(0f, 0f, 26.4f), new Vector3(8f, 1.4f, 6f), true);
            _ctx.MarkPoint("S1.IslandA", new Vector3(0f, 0f, 26.4f));

            var p2 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(0f, 0f, 34.1f), null, new[] { Vector3.zero, new Vector3(0f, 0f, 8f) },
                new Vector3(5f, 0.4f, 9f), 2.0f, 3.2f, PlatformLoop.PingPong);
            _ctx.Mark("S1.P2", p2.gameObject);
            // sweeper riding on P2 (root follows the platform body; hub at the platform centre)
            var sw = PuzzleKit.SweeperArm(_ctx.Hazards, new Vector3(0f, 0f, 34.1f), null, 4.4f, 55f, 0.6f);
            var baseCol = sw.transform.Find("Base");
            if (baseCol != null) { var bc = baseCol.GetComponent<Collider>(); if (bc != null) Kit.SafeDestroy(bc); }
            var follow = sw.gameObject.AddComponent<L5FollowBody>();
            follow.Target = p2.Body;
            _ctx.Mark("S1.Sweeper", sw.gameObject);
            // bus-style rules painted on P2
            var deckSign = PuzzleVisuals.Text(p2.Body.transform, "BusRule", new Vector3(0f, 0.02f, -3.65f), PuzzleVisuals.Facing(Vector3.up),
                "STAND AT THE BACK", 4f, UIColors.AccentYellow, 4.6f, 0.6f);
            deckSign.fontStyle = TMPro.FontStyles.Bold;
            PuzzleVisuals.StripedBox(p2.Body.transform, "SafeLine", new Vector3(0f, 0.012f, -2.75f), new Vector3(4.9f, 0.02f, 0.18f), 0, 0.3f, false);

            EnvKit.Platform(t, new Vector3(-6.25f, 0f, 38.6f), new Vector3(7.1f, 1.4f, 3.6f), true);
            _ctx.MarkPoint("S1.IslandB", new Vector3(-6.25f, 0f, 38.6f));

            var p3 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(-6.25f, 0f, 42.6f), null, new[] { Vector3.zero, new Vector3(0f, 2f, 8f) },
                new Vector3(4f, 0.4f, 4f), 2.2f, 2.6f, PlatformLoop.PingPong);
            _ctx.Mark("S1.P3", p3.gameObject);

            // C1 floor
            var c1 = _ctx.Section("C1_Landing", Vector3.zero);
            Floor(c1, new Vector3(0f, S2Y, 58.8f), new Vector3(20f, 1f, 12f), MatKey.Floor);
            _ctx.Checkpoint(new Vector3(-3f, S2Y, 57.5f), 0f);

            // dressing
            PostSign(t, new Vector3(-3.6f, 1.6f, 10.6f), FaceSouth, "MIND THE GAP\n(IT'S BOTTOMLESS)", 2.6f, 1.0f, SignStyle.Danger, 0f);
            PostSign(t, new Vector3(0f, 2.75f, 29.2f), FaceSouth, "SWEEPER ZONE: STAY AT THE BACK. LIKE ON A BUS.", 5.6f, 0.6f, SignStyle.Danger, 0f, true);
            EnvKit.Pillar(t, new Vector3(3.4f, 0f, 24f), 3.2f, 0.7f);
            Sign(t, new Vector3(3.4f, 2.2f, 23.6f), FaceSouth, "SHIFT CHANGE IN:\nNEVER", 1.4f, 0.8f, SignStyle.Info);
            Beacon(t, new Vector3(-3.4f, 0f, 24.2f));
            Beacon(t, new Vector3(-9.3f, 0f, 37.2f));
            EnvKit.Decor.Debris(t, new Vector3(2.2f, 0f, 28.2f), 0.9f, 8, 21);
            EnvKit.Decor.BrokenBeam(t, new Vector3(-9.2f, 0f, 39.6f), Yaw(80f), 2.4f);
            Sign(c1, new Vector3(-9.97f, S2Y + 1.6f, 54.6f), Yaw(90f), "SHIFT 1 OF 5 SURVIVED\n(SO FAR)", 2.4f, 1.0f, SignStyle.Info);   // on the C1 wall, clear of the P3 landing
            EnvKit.Decor.CrateStack(c1, new Vector3(-8.6f, S2Y, 62.6f), Yaw(15f), 3, 4);
            Beacon(c1, new Vector3(9.4f, S2Y, 53.4f), true);
            EnvKit.Decor.SparkingPanel(c1, new Vector3(-9.99f, S2Y + 1.4f, 58f), Face(Yaw(90f)));   // flush with the wall face
            EnvKit.Wall(c1, new Vector3(-10.2f, S2Y, 52.8f), new Vector3(-10.2f, S2Y, 64.8f), 3.5f, 0.4f, MatKey.WallAlt);

            _ctx.Tutorial(new Vector3(0f, 1.5f, 8f), new Vector3(10f, 4f, 5f), "l5_commute", "THE COMMUTE",
                "Shuttles pause at every dock. Board when one arrives - all together if you dare. On the long one, stay behind the stripe: the sweeper is not a seat.", null, false);
            _ctx.Hint(new Vector3(0f, 1.5f, 20f), new Vector3(16f, 6f, 30f),
                "Wait for each shuttle to dock, ride it standing still, and on the sweeper shuttle stay in the striped back zone and step off sideways onto the left island.",
                "Patience. The platforms come back. The sweeper does too.");
        }

        // ================================================================== S2 laser hall
        void BuildS2()
        {
            var t = _ctx.Section("S2_LaserHall", Vector3.zero);
            // hall floor segments (gaps are filled by the electric tiles)
            Floor(t, new Vector3(0f, S2Y, 67.6f), new Vector3(8f, 1f, 5.6f), MatKey.FloorAlt);
            Floor(t, new Vector3(0f, S2Y, 74.7f), new Vector3(8f, 1f, 3.4f), MatKey.FloorAlt);
            Floor(t, new Vector3(0f, S2Y, 89.8f), new Vector3(8f, 1f, 21.6f), MatKey.FloorAlt);
            var e1 = PuzzleKit.ElectricFloor(_ctx.Hazards, new Vector3(0f, S2Y, 71.7f), null, new Vector2(8f, 2.6f), 2.0f, 2.8f, 0.8f);
            var e2 = PuzzleKit.ElectricFloor(_ctx.Hazards, new Vector3(0f, S2Y, 77.7f), null, new Vector2(8f, 2.6f), 2.0f, 2.8f, 2.4f);
            _ctx.Mark("S2.E1", e1.gameObject); _ctx.Mark("S2.E2", e2.gameObject);
            // walls
            EnvKit.Wall(t, new Vector3(-4.2f, S2Y, 64.8f), new Vector3(-4.2f, S2Y, 100.6f), 4.5f, 0.4f, MatKey.Wall);
            EnvKit.Wall(t, new Vector3(4.2f, S2Y, 64.8f), new Vector3(4.2f, S2Y, 100.6f), 4.5f, 0.4f, MatKey.Wall);

            // first half: cycling lasers
            float[] lz = { 68.6f, 74.6f, 80.6f };
            float[] lph = { 0f, 1.5f, 3.0f };
            for (int i = 0; i < 3; i++)
            {
                var lb = PuzzleKit.LaserBarrier(_ctx.Hazards, new Vector3(0f, S2Y, lz[i]), null, 7.4f, 3, 2.0f, 2.6f, lph[i]);
                _ctx.Mark("S2.L" + (i + 1), lb.gameObject);
            }
            // second half: always-on lasers, killed by the override lever
            var lever = PuzzleKit.Lever(_ctx.Puzzles, new Vector3(7.5f, S2Y, 90.2f), Yaw(180f), 0, true, false, "LASER OVERRIDE: SECOND HALF OFF");
            _ctx.Mark("S2.Lever", lever.gameObject);
            var blockers = new List<Behaviour>();
            float[] hz = { 88.6f, 92.1f, 95.6f };
            for (int i = 0; i < 3; i++)
            {
                var lb = PuzzleKit.LaserBarrier(_ctx.Hazards, new Vector3(0f, S2Y, hz[i]), null, 7.4f, 3);
                blockers.Add(lb);
                _ctx.Mark("S2.H" + (i + 1), lb.gameObject);
            }
            var toggle = PuzzleKit.HazardToggle(_ctx.Puzzles, blockers.ToArray(), false, lever);
            _ctx.Mark("S2.LaserToggle", toggle.gameObject);
            for (int i = 0; i < 3; i++)
                PuzzleKit.IndicatorLight(t, new Vector3(-3.9f, S2Y + 2.6f, hz[i]), Yaw(90f), true, lever);
            Sign(t, new Vector3(0f, S2Y + 4.0f, 86.4f), FaceSouth, "SECOND HALF: ALWAYS ON\n(OVERRIDE: MAINTENANCE LEDGE)", 5f, 1.0f, SignStyle.Danger);   // above the follow camera
            BannerRods(t, new Vector3(0f, S2Y + 4.0f, 86.4f), 2.5f, 4.0f, 0.07f);

            // turbo-only crumbling catwalk to the override lever (outside the right wall)
            Floor(t, new Vector3(7.5f, S2Y, 66.2f), new Vector3(3f, 1f, 2.8f), MatKey.FloorAlt);
            float[] tz = { 69.95f, 74.55f, 79.15f, 83.75f };
            for (int i = 0; i < tz.Length; i++)
            {
                var cp = PuzzleKit.CrumblingPlatform(_ctx.Hazards, new Vector3(7.5f, S2Y, tz[i]), null, new Vector3(2.5f, 0.5f, 4.5f));
                _ctx.Mark("S2.Crumble" + (i + 1), cp.gameObject);
            }
            Floor(t, new Vector3(7.5f, S2Y, 88.85f), new Vector3(3f, 1f, 5.5f), MatKey.Floor);
            Floor(t, new Vector3(7.5f, S2Y, 96.1f), new Vector3(3f, 1f, 9f), MatKey.FloorAlt);
            EnvKit.Railing(t, new Vector3(9.05f, S2Y, 86.2f), new Vector3(9.05f, S2Y, 100.4f));
            PerspectiveKit.SpeedRoute(t, new[] { new Vector3(7.5f, S2Y, 60f), new Vector3(7.5f, S2Y, 86.6f), new Vector3(7.5f, S2Y, 89f) }, 1.1f, 1.2f);
            PostSign(t, new Vector3(9.0f, S2Y + 1.4f, 63.4f), Yaw(-150f), "TURBO LEGS ONLY.\nNO, REALLY.", 2.0f, 0.9f, SignStyle.Danger, S2Y);   // beside the run-up, clear of the sprint line
            PostSign(t, new Vector3(7.5f, S2Y + 2.4f, 91.4f), FaceSouth, "MAINTENANCE LEDGE", 2.6f, 0.5f, SignStyle.Info, S2Y, true);
            _ctx.MarkPoint("S2.TurboStart", new Vector3(7.5f, S2Y, 59.5f));
            _ctx.MarkPoint("S2.TurboEnd", new Vector3(7.5f, S2Y, 88.6f));
            _ctx.MarkPoint("S2.LedgeExit", new Vector3(7.5f, S2Y, 99.5f));

            // bot stand spots (safe strips between hazards)
            float[] safe = { 66.6f, 69.75f, 73.8f, 75.6f, 79.8f, 82.6f, 86.6f };
            for (int i = 0; i < safe.Length; i++) _ctx.MarkPoint("S2.Safe" + i, new Vector3(0f, S2Y, safe[i]));
            _ctx.MarkPoint("S2.HallEnd", new Vector3(0f, S2Y, 98.5f));

            // dressing
            Sign(t, new Vector3(0f, S2Y + 3.9f, 65.1f), FaceSouth, "LASER HALL: NO RUNNING. ACTUALLY, RUN.", 6.2f, 0.7f, SignStyle.Danger);   // above the follow camera
            BannerRods(t, new Vector3(0f, S2Y + 3.9f, 65.1f), 3.1f, 4.0f, 0.07f);
            for (int i = 0; i < 4; i++)
            {
                float z = 68f + i * 8.5f;
                Lamp(t, new Vector3(-3.95f, S2Y + 3.6f, z), Yaw(90f), i % 2 == 0 ? Red : Amber, i == 1, 1.6f, 0.3f, 2f);
                Lamp(t, new Vector3(3.95f, S2Y + 3.6f, z + 4f), Yaw(-90f), i % 2 == 0 ? Amber : Red, false, 1.6f, 0.3f, 2f);
            }
            EnvKit.Decor.SparkingPanel(t, new Vector3(3.98f, S2Y + 1.5f, 85f), Face(Yaw(-90f)));
            EnvKit.Decor.SparkingPanel(t, new Vector3(-3.98f, S2Y + 1.5f, 77f), Face(Yaw(90f)));
            EnvKit.Poster(t, new Vector3(-3.97f, S2Y + 1.7f, 91f), Face(Yaw(90f)), "TIMING IS EVERYTHING", "SHIFT WHEN THE LASERS DO");
            EnvKit.Poster(t, new Vector3(3.97f, S2Y + 1.7f, 97f), Face(Yaw(-90f)), "LASERS: 9 OUT OF 10", "INTERNS CAN'T FEEL THEIR TOES");
            Beacon(t, new Vector3(-3.9f, S2Y + 4.6f, 86.5f));
            Beacon(t, new Vector3(3.9f, S2Y + 4.6f, 70f));
            EnvKit.Pipe(t, new[] { new Vector3(-4.6f, S2Y + 4.2f, 64.8f), new Vector3(-4.6f, S2Y + 4.2f, 100.6f) }, 0.18f);
            EnvKit.Pipe(t, new[] { new Vector3(4.6f, S2Y + 3.8f, 64.8f), new Vector3(4.6f, S2Y + 3.8f, 100.6f) }, 0.14f);

            // C2
            var c2 = _ctx.Section("C2_Landing", Vector3.zero);
            Floor(c2, new Vector3(-1f, S2Y, 106.6f), new Vector3(22f, 1f, 12f), MatKey.Floor);
            _ctx.Checkpoint(new Vector3(-1f, S2Y, 105.8f), 0f);
            EnvKit.Decor.CrateStack(c2, new Vector3(8.6f, S2Y, 102.2f), Yaw(-20f), 2, 7);
            Beacon(c2, new Vector3(-11.4f, S2Y, 101.2f));
            PostSign(c2, new Vector3(4.5f, S2Y + 1.5f, 111.9f), FaceSouth, "SECURITY ZONE AHEAD\nBONK-BOTS: NOW 40% MORE BONK", 4f, 1.0f, SignStyle.Danger, S2Y, true);

            _ctx.Tutorial(new Vector3(0f, 3.5f, 62f), new Vector3(18f, 4f, 6f), "l5_lasers", "LASER HALL",
                "Lasers and electric floors cycle. Yellow emitter = about to fire. The second half never switches off... unless somebody fast finds the maintenance ledge.", null, false);
            _ctx.Hint(new Vector3(2.5f, S2Y + 2f, 80f), new Vector3(16f, 6f, 34f),
                "Cross the first half one hazard at a time when it is off. Your TURBO LEGS sprinter must sprint the crumbling catwalk outside the right wall (tiles drop 0.6 s after you touch them) and pull the LASER OVERRIDE lever.",
                "Some floors only hold you if you're fast. Very fast.");
        }

        // ================================================================== S3 bot arena + physics chain
        void BuildS3()
        {
            var t = _ctx.Section("S3_BotArena", Vector3.zero);
            float y = ArenaY;
            Floor(t, new Vector3(2f, y, 128.1f), new Vector3(22f, 1f, 31f), MatKey.Floor);
            // bot-proof catwalk (1.6 m above the arena floor; bots can't reach targets > 1.3 m up)
            _ctx.Platform(t, new Vector3(-10.5f, S2Y, 122.6f), new Vector3(3f, 2.4f, 20f), MatKey.FloorAlt, true, "Catwalk");
            EnvKit.Railing(t, new Vector3(-9f, S2Y, 112.6f), new Vector3(10f, S2Y, 112.6f));
            EnvKit.Railing(t, new Vector3(-9.05f, S2Y, 113f), new Vector3(-9.05f, S2Y, 123.2f));
            EnvKit.Wall(t, new Vector3(-12.2f, y, 112.6f), new Vector3(-12.2f, y, 143.6f), 5.6f, 0.4f, MatKey.WallAlt);
            EnvKit.Wall(t, new Vector3(-9.2f, y, 132.6f), new Vector3(-9.2f, y, 143.6f), 4f, 0.4f, MatKey.WallAlt);
