            // ---- physics chain: glass shelf + barrel over the caged 25 kg dock plate
            var cageC = new Vector3(-7.6f, y, 127f);
            float cageH = 2.0f, half = 1.15f;
            for (int s = -1; s <= 1; s += 2)
            {
                Kit.SolidBox(t, "CageX", cageC + new Vector3(s * half, cageH * 0.5f, 0f), new Vector3(0.1f, cageH, half * 2f + 0.1f), MatKey.Grate, 0.01f);
                Kit.SolidBox(t, "CageZ", cageC + new Vector3(0f, cageH * 0.5f, s * half), new Vector3(half * 2f + 0.1f, cageH, 0.1f), MatKey.Grate, 0.01f);
                for (int k = -1; k <= 1; k += 2)
                    Kit.BoxVisual(t, "CagePost", cageC + new Vector3(s * half, cageH * 0.5f, k * half), new Vector3(0.18f, cageH + 0.1f, 0.18f), MatKey.HazardYellow, 0.02f);
            }
            var dockPlate = PuzzleKit.PressurePlate(_ctx.Puzzles, cageC, null, 25f, true, "CHARGING DOCK POWERED");
            _ctx.Mark("S3.DockPlate", dockPlate.gameObject);
            float glassY = y + cageH + 0.05f;
            var glass = PuzzleKit.GlassPane(_ctx.Puzzles, new Vector3(cageC.x, glassY, cageC.z - 1.1f), Quaternion.Euler(90f, 0f, 0f), new Vector2(2.2f, 2.2f));
            _ctx.Mark("S3.Glass", glass.gameObject);
            var barrel = PuzzleKit.Barrel(_ctx.Props, new Vector3(cageC.x, glassY + 0.08f, cageC.z));
            _ctx.Mark("S3.Barrel", barrel.gameObject);
            _ctx.MarkPoint("S3.GlassAim", new Vector3(cageC.x + 0.6f, glassY + 0.02f, cageC.z - 0.7f));
            PerspectiveKit.ShootHint(t, new Vector3(cageC.x + 0.6f, glassY + 0.12f, cageC.z - 0.7f), 0.45f);
            Sign(t, new Vector3(cageC.x + 1.25f, y + 1.3f, cageC.z), Yaw(90f), "DOCK POWER\nPLATE (25 KG)", 1.6f, 0.7f, SignStyle.Info);   // faces the arena
            PostSign(t, new Vector3(cageC.x, y + cageH + 1.35f, cageC.z + half - 0.07f), FaceSouth, "BARREL STORAGE (GLASS SHELF.\nWHAT COULD GO WRONG?)", 2.8f, 0.7f, SignStyle.Info, y + cageH, true);   // on the cage

            // ---- bots, dock, holding cell
            var botB = EnemyKit.SecurityBot(_ctx.Enemies, new Vector3(3f, y, 120.5f), Quaternion.identity,
                new[] { new Vector3(-2f, y, 120f), new Vector3(8f, y, 120f), new Vector3(8f, y, 129f), new Vector3(-2f, y, 129f) },
                "L5_CELL", new Vector3(3f, y, 124.5f), 8f);
            _ctx.Mark("S3.BotB", botB.gameObject);
            var botA = EnemyKit.SecurityBot(_ctx.Enemies, new Vector3(1f, y, 136f), Yaw(90f),
                new[] { new Vector3(-5f, y, 135.5f), new Vector3(7f, y, 135.5f), new Vector3(7f, y, 141f), new Vector3(-5f, y, 141f) },
                "L5_CELL", new Vector3(1f, y, 138.3f), 7.5f);
            _ctx.Mark("S3.BotA", botA.gameObject);

            var dockRoot = Kit.Make("ChargingDock", t, new Vector3(10.7f, y, 138.5f), Yaw(-90f));
            var dt = dockRoot.transform;
            Kit.BoxVisual(dt, "Pad", new Vector3(0f, 0.04f, 0f), new Vector3(2.2f, 0.08f, 2.2f), MatKey.MetalDark, 0.02f);
            Kit.BoxVisual(dt, "PadGlow", new Vector3(0f, 0.085f, 0f), new Vector3(1.6f, 0.01f, 1.6f), MatKey.LightBlue, 0f, null, false);
            Kit.SolidBox(dt, "ChargerPost", new Vector3(0f, 1.3f, -1.25f), new Vector3(1.6f, 2.6f, 0.35f), MatKey.PuzzleBody, 0.04f);
            Kit.BoxVisual(dt, "Bolt", new Vector3(0f, 1.9f, -1.06f), new Vector3(0.5f, 0.7f, 0.04f), MatKey.HazardYellow, 0.01f, null, false);
            var dockLamp = PuzzleVisuals.Lamp(dt, "DockLamp", new Vector3(0f, 2.75f, -1.25f), Quaternion.Euler(-90f, 0f, 0f), 0.2f);
            var dockText = PuzzleVisuals.Text(dt, "DockStatus", new Vector3(0f, 1.15f, -1.06f), PuzzleVisuals.Facing(Vector3.forward), "DOCK: NO POWER", 2.2f, UIColors.Text, 1.5f, 0.4f);
            var dockPoint = Kit.Make("DockPoint", dt, new Vector3(0f, 0.08f, 0f), Quaternion.identity).transform;
            var dock = dockRoot.AddComponent<L5ChargingDock>();
            dock.Bot = botA; dock.DockPoint = dockPoint; dock.Status = dockText; dock.Lamp = dockLamp;
            PuzzleKit.Wire(dock, dockPlate);
            _ctx.Mark("S3.Dock", dockRoot);
            PuzzleKit.CableBetween(t, dockPlate, dockRoot.transform);
            Sign(t, new Vector3(12.95f, y + 3f, 138.5f), Yaw(-90f), "BONK-BOT CHARGING DOCK", 3f, 0.6f, SignStyle.Info);

            var cell = EnemyKit.HoldingCell(_ctx.Enemies, new Vector3(10.6f, y, 117.5f), Yaw(-90f), "L5_CELL");
            var cellLever = PuzzleKit.Lever(_ctx.Puzzles, new Vector3(-11.3f, S2Y, 118f), Yaw(90f), 0, false, false, "");
            PuzzleKit.Wire(cell, cellLever);
            _ctx.Mark("S3.Cell", cell.gameObject);
            _ctx.Mark("S3.CellLever", cellLever.gameObject);
            Sign(t, new Vector3(-11.95f, S2Y + 1.6f, 118f), Yaw(90f), "CELL RELEASE\n(NO QUESTIONS ASKED)", 2.2f, 0.8f, SignStyle.Info);

            // ---- heavy plate door (150 kg, latching)
            var plate = PuzzleKit.PressurePlate(_ctx.Puzzles, new Vector3(-4f, y, 138.6f), null, Tuning.PlateHeavy, true, "SECURITY DOOR OPEN");
            _ctx.Mark("S3.Plate", plate.gameObject);
            var door = PuzzleKit.Door(_ctx.Puzzles, new Vector3(0f, y, 143.8f), null, DoorMode.SlideUp, 4f, 4.2f, plate);
            _ctx.Mark("S3.Door", door.gameObject);
            PuzzleKit.Cable(t, new Vector3(-4f, y, 139.7f), new Vector3(-2.3f, y, 143.4f), plate);
            _ctx.MarkPoint("S3.PlateA", new Vector3(-4.4f, y, 138.2f));
            _ctx.MarkPoint("S3.PlateB", new Vector3(-3.55f, y, 139.05f));
            _ctx.MarkPoint("S3.DoorIn", new Vector3(0f, y, 141.5f));

            // ---- cover + dressing
            EnvKit.Decor.CrateStack(t, new Vector3(4f, y, 125f), Yaw(10f), 3, 3);
            EnvKit.Decor.CrateStack(t, new Vector3(-0.5f, y, 131.5f), Yaw(-25f), 2, 9);
            EnvKit.Decor.BrokenBeam(t, new Vector3(9.5f, y, 128f), Yaw(160f), 3.6f);
            EnvKit.Decor.Debris(t, new Vector3(6f, y, 133f), 1.5f, 12, 31);
            Beacon(t, new Vector3(-9.6f, S2Y + 3.6f, 143.4f), true);
            Beacon(t, new Vector3(12.8f, y + 4.5f, 113f));
            Lamp(t, new Vector3(12.95f, y + 3.6f, 124f), Yaw(-90f), Amber, true, 2.2f, 0.4f, 2.4f);
            Lamp(t, new Vector3(-11.95f, S2Y + 3.2f, 126f), Yaw(90f), Red, false, 2.2f, 0.4f, 2f);
            EnvKit.Decor.SparkingPanel(t, new Vector3(12.97f, y + 1.4f, 131f), Face(Yaw(-90f)));
            EnvKit.Poster(t, new Vector3(-11.97f, S2Y + 1.6f, 114.8f), Face(Yaw(90f)), "NIGHT SHIFT ONLY", "DO NOT FEED THE ROBOTS");
            Sign(t, new Vector3(0f, y + 5.4f, 143.55f), FaceSouth, "EXIT  (150 KG CLEARANCE REQUIRED)", 5f, 0.6f, SignStyle.Exit);

            // C3
            var c3 = _ctx.Section("C3_Landing", Vector3.zero);
            Floor(c3, new Vector3(0f, y, 149.6f), new Vector3(16f, 1f, 12f), MatKey.Floor);
            _ctx.Checkpoint(new Vector3(0f, y, 149f), 0f);
            Beacon(c3, new Vector3(7.4f, y, 144.2f));

            _ctx.Tutorial(new Vector3(-10.5f, S2Y + 1.5f, 116f), new Vector3(3.5f, 4f, 6f), "l5_bots", "BONK-BOTS",
                "Two security bots. They can't reach you up on this catwalk. A bot on a powered charging dock takes a nap. Captured interns go to the cell - the release lever is up here.", null, false);
            _ctx.Hint(new Vector3(-2f, y + 2f, 128f), new Vector3(24f, 7f, 31f),
                "Shoot the glass shelf from the catwalk: the barrel drops onto the caged 25 kg plate and the door bot goes to sleep. Then drop off the catwalk's far end and put your Brute plus one more on the 150 kg plate.",
                "That barrel is one bad decision away from being useful.");
        }

        // ================================================================== S4 counterweight crusher
        void BuildS4()
        {
            var t = _ctx.Section("S4_Counterweight", Vector3.zero);
            float y = DeckY;
            Floor(t, new Vector3(0f, y, 160.65f), new Vector3(16f, 1f, 10.1f), MatKey.Floor);
            Floor(t, new Vector3(-6.45f, y, 167.95f), new Vector3(3.1f, 1f, 4.5f), MatKey.FloorAlt);
            Floor(t, new Vector3(0f, y, 167.95f), new Vector3(2.2f, 1f, 4.5f), MatKey.FloorAlt);

            // tops sit 6 cm below the deck: a flush seam makes the pushed block snag on the basket edge (speculative contact)
            var lift = PuzzleKit.PulleyLift(_ctx.Puzzles, new Vector3(0f, PitY - 0.06f, 168f), null, 6f, 6f, new Vector2(3.6f, 4.4f), 0f);
            _ctx.Mark("S4.Lift", lift.gameObject);
            var yoke = lift.PlatformB != null ? lift.PlatformB.transform.Find("Yoke") : null;
            if (yoke != null) { var r = yoke.GetComponent<Renderer>(); if (r != null) r.enabled = false; }

            // dispatch lever rides on platform A
            var lever = PuzzleKit.Lever(lift.PlatformA.transform, new Vector3(-1.3f, 0f, 0.7f), Yaw(90f), 0, false, false, "");
            _ctx.Mark("S4.Dispatch", lever.gameObject);
            var brakeGo = Kit.Make("PulleyBrake", t, new Vector3(-6.4f, y, 164.4f), Quaternion.identity);
            Kit.SolidBox(brakeGo.transform, "Console", new Vector3(0f, 0.6f, 0f), new Vector3(1.4f, 1.2f, 0.6f), MatKey.PuzzleBody, 0.04f);
            var disp = PuzzleVisuals.Display(brakeGo.transform, "BrakeDisplay", new Vector3(0f, 2.1f, 0f), 2.4f, 0.8f);
            var status = PuzzleVisuals.Text(disp, "Status", Vector3.zero, Quaternion.identity, "BRAKE ON", 2.6f, UIColors.AccentYellow, 2.3f, 0.75f);
            var brake = brakeGo.AddComponent<L5PulleyBrake>();
            brake.Lift = lift; brake.Status = status;
            lift.enabled = false;
            PuzzleKit.Wire(brake, lever);
            _ctx.Mark("S4.Brake", brakeGo);

            // the heavy block and the basket crusher (head stops 1.75 m above the basket: blocks fit, adults don't)
            var block = PuzzleKit.HeavyBlock(_ctx.Props, new Vector3(3f, y, 163.0f));
            _ctx.Mark("S4.Block", block.gameObject);
            _ctx.MarkPoint("S4.BlockGoal", new Vector3(3f, y, 168f));
            _ctx.MarkPoint("S4.PushStart", new Vector3(3f, y, 161.4f));
            var crusher = PuzzleKit.Crusher(_ctx.Hazards, new Vector3(3f, y + 1.73f, 168f), null, new Vector2(4.2f, 2.4f), 1.5f, 1.8f, 0f, lever);
            crusher.Invert = true;
            PuzzleKit.Wire(crusher, lever);
            _ctx.Mark("S4.Crusher", crusher.gameObject);
            Kit.SolidBox(t, "CrusherLegW", new Vector3(0.6f, (y + y + 1.73f) * 0.5f, 168f), new Vector3(0.4f, 1.73f, 0.6f), MatKey.MetalDark);
            Kit.SolidBox(t, "CrusherLegE", new Vector3(5.4f, (PitY + y + 1.73f) * 0.5f, 168f), new Vector3(0.4f, y + 1.73f - PitY, 0.6f), MatKey.MetalDark);

            // marks for the bots
            _ctx.MarkPoint("S4.A_Brainiac", new Vector3(-2.2f, y, 167.0f));
            _ctx.MarkPoint("S4.A_Brute", new Vector3(-2.5f, y, 169.2f));
            _ctx.MarkPoint("S4.A_Approach", new Vector3(-2.6f, y, 164.6f));
            _ctx.MarkPoint("S4.B_Approach", new Vector3(4.35f, y, 165.0f));
            _ctx.MarkPoint("S4.B_North", new Vector3(4.2f, y, 169.75f));
            _ctx.MarkPoint("S4.Top", new Vector3(-3f, UpperY, 172.4f));

            // upper deck
            var u = _ctx.Section("S4_UpperDeck", Vector3.zero);
            Floor(u, new Vector3(-2.8f, UpperY, 188.2f), new Vector3(14.4f, 1f, 36f), MatKey.Floor);
            _ctx.Checkpoint(new Vector3(-4f, UpperY, 176.5f), 0f);

            // dressing + readability
            PostSign(t, new Vector3(-3f, UpperY + 2.6f, 170.3f), FaceSouth, "PASSENGERS", 3.8f, 0.6f, SignStyle.Info, UpperY, true);   // arch over A's exit onto the upper deck
            PostSign(t, new Vector3(2.8f, UpperY + 2.6f, 170.3f), FaceSouth, "COUNTERWEIGHT BASKET\n(INTERNS WELCOME)", 3.2f, 0.9f, SignStyle.Info, UpperY, true);
            PostSign(t, new Vector3(6.6f, y + 1.7f, 163.5f), Yaw(-150f), "CRUSHER CALIBRATED FOR\nPERSONNEL OVER 1.75 M", 2.8f, 0.9f, SignStyle.Danger, y);
            PostSign(t, new Vector3(-6.4f, y + 3.1f, 164.1f), FaceSouth, "HEAVIER SIDE SINKS. SHIFT YOUR WEIGHT.", 3.2f, 0.5f, SignStyle.Info, y, true);
            PerspectiveKit.Clue(t, new Vector3(-6.4f, y + 1.0f, 164.08f), Quaternion.identity, "BASKET > PASSENGERS + 10 KG", 0.22f);
            PerspectiveKit.Clue(t, new Vector3(3f, y + 0.05f, 162.0f), Quaternion.Euler(90f, 0f, 0f), "BLOCK + 1 INTERN", 0.4f);
            Beacon(t, new Vector3(-7.4f, y, 156.2f), true);
            Beacon(t, new Vector3(7.4f, y, 165.2f));
            EnvKit.Decor.SparkingPanel(t, new Vector3(-6.5f, y + 2.3f, 170.15f), Face(FaceSouth));   // on the upper deck's front face
            EnvKit.Decor.Debris(t, new Vector3(-5.5f, y, 158.5f), 1.4f, 10, 41);
            Lamp(t, new Vector3(0.9f, UpperY + 0.2f, 170.15f), FaceSouth, Amber, true, 4f, 0.35f, 2.2f);   // clear of platform A's exit

            _ctx.Tutorial(new Vector3(0f, y + 1.5f, 158f), new Vector3(16f, 4f, 5f), "l5_pulley", "COUNTERWEIGHT",
                "The braked lift moves when someone pulls DISPATCH on the passenger platform. The heavier side sinks - the basket must outweigh the passengers by 10 kg.", null, false);
            _ctx.Hint(new Vector3(0f, y + 2f, 164f), new Vector3(16f, 7f, 14f),
                "Brute pushes the heavy block into the basket (time it with the crusher), the Sprinter joins the block in the basket, Brute + Brainiac ride the passenger platform and pull DISPATCH. The basket goes down to the maintenance shaft.",
                "160 kg is heavy. 160 kg plus a friend is heavier.");
        }

        // ================================================================== S5 escape pod + roof gauntlet
        void BuildS5()
        {
            var t = _ctx.Section("S5_EscapePod", Vector3.zero);
            var deckLaser = PuzzleKit.LaserBarrier(_ctx.Hazards, new Vector3(-2.8f, UpperY, 186f), null, 13.6f, 3, 2.2f, 2.8f, 0.5f);
            _ctx.Mark("S5.DeckLaser", deckLaser.gameObject);
            _ctx.MarkPoint("S5.DeckSafe0", new Vector3(-2f, UpperY, 184f));
            _ctx.MarkPoint("S5.DeckSafe1", new Vector3(-2f, UpperY, 188.6f));

            // the pod
            var exitGo = _ctx.Exit(new Vector3(0f, UpperY, 200f), 0f);
            var exit = exitGo != null ? exitGo.GetComponent<LevelExit>() : null;
            if (exit != null)
            {
                exit.ZoneCenter = new Vector3(0f, 3.6f, 2.2f);
                exit.ZoneSize = new Vector3(4.4f, 7.2f, 4.4f);
                var floorT = exitGo.transform.Find("CabFloor");
                var sensor = exitGo.AddComponent<WeightSensor>();
                sensor.Surfaces = floorT != null ? new[] { floorT.GetComponent<Collider>() } : new Collider[0];
                var lim = exitGo.AddComponent<L5PodWeightLimit>();
                lim.Exit = exit; lim.Sensor = sensor; lim.MaxKg = PodMaxKg;
                var board = Kit.Make("PodCapacity", exitGo.transform, new Vector3(-3.6f, 2.6f, -0.35f), Quaternion.identity);
                Kit.BoxVisual(board.transform, "Board", Vector3.zero, new Vector3(2.4f, 1.5f, 0.12f), MatKey.MetalDark, 0.03f);
                PuzzleVisuals.Text(board.transform, "Title", new Vector3(0f, 0.45f, -0.07f), Quaternion.identity, "ESCAPE POD", 3f, UIColors.AccentYellow, 2.2f, 0.4f);
                lim.Readout = PuzzleVisuals.Text(board.transform, "Readout", new Vector3(0f, -0.2f, -0.07f), Quaternion.identity, "0 / 200 KG", 3.4f, UIColors.Text, 2.2f, 0.8f);
                Kit.BoxVisual(board.transform, "Post", new Vector3(0f, -1.65f, 0.1f), new Vector3(0.15f, 1.9f, 0.15f), MatKey.MetalDark, 0.01f);
                lim.AlarmLamps = new[]
                {
                    PuzzleVisuals.Lamp(exitGo.transform, "PodLampL", new Vector3(-2.25f, 4.4f, -0.32f), Quaternion.identity, 0.22f, PuzzleLampColor.Green),
                    PuzzleVisuals.Lamp(exitGo.transform, "PodLampR", new Vector3(2.25f, 4.4f, -0.32f), Quaternion.identity, 0.22f, PuzzleLampColor.Green)
                };
                // roof hatch dressing
                Kit.BoxVisual(exitGo.transform, "RoofHatch", new Vector3(0f, 4.92f, 2.6f), new Vector3(1.4f, 0.06f, 1.4f), MatKey.HazardYellow, 0.02f, null, false);
                Kit.BoxVisual(exitGo.transform, "RoofHatchLid", new Vector3(0f, 4.96f, 2.6f), new Vector3(1.1f, 0.04f, 1.1f), MatKey.MetalLight, 0.02f, null, false);
                // painted beside the hatch, upright for the rider who arrives from the shaft side (+X) walking west
                PuzzleVisuals.Text(exitGo.transform, "RoofLabel", new Vector3(1.3f, 4.995f, 2.6f), Quaternion.LookRotation(Vector3.down, Vector3.left), "ROOF SEAT (NO SEATBELT)", 2.4f, UIColors.AccentYellow, 3.6f, 0.4f);
                // the kit's dark EXIT lettering vanishes on its orange board against the Chaos backlight: white stays readable
                var exitText = exitGo.transform.Find("ExitSign/ExitText");
                var exitTmp = exitText != null ? exitText.GetComponent<TMPro.TextMeshPro>() : null;
                if (exitTmp != null) exitTmp.color = Color.white;
                _ctx.Mark("S5.Pod", exitGo);
            }
            _ctx.MarkPoint("S5.CabA", new Vector3(-0.9f, UpperY + 0.1f, 202.6f));
            _ctx.MarkPoint("S5.CabB", new Vector3(0.9f, UpperY + 0.1f, 202.0f));
            _ctx.MarkPoint("S5.PodFront", new Vector3(0f, UpperY, 196.5f));
            _ctx.MarkPoint("S5.Roof", new Vector3(0.3f, RoofY, 202.4f));

            // ---- maintenance shaft gauntlet (pit -> roof): vertical lifts + lasers
            var g = _ctx.Section("S5_Gauntlet", Vector3.zero);
            Floor(g, new Vector3(7f, PitY, 170.05f), new Vector3(4f, 0.6f, 7.5f), MatKey.Grate);
            var v1 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(7f, PitY, 175.9f), null, new[] { Vector3.zero, new Vector3(0f, 4f, 0f) }, new Vector3(3.8f, 0.4f, 4f), 1.8f, 2.6f, PlatformLoop.PingPong);
            Floor(g, new Vector3(7f, 1.4f, 182.05f), new Vector3(4f, 0.6f, 8.1f), MatKey.Grate);
            var gl1 = PuzzleKit.LaserBarrier(_ctx.Hazards, new Vector3(7f, 1.4f, 182f), null, 3.4f, 3, 1.8f, 2.4f, 0f);
            var v2 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(7f, 1.4f, 188.15f), null, new[] { Vector3.zero, new Vector3(0f, 4f, 0f) }, new Vector3(3.8f, 0.4f, 4f), 1.8f, 2.6f, PlatformLoop.PingPong);
            Floor(g, new Vector3(7f, 5.4f, 193.2f), new Vector3(4f, 0.6f, 6f), MatKey.Grate);
            var gl2 = PuzzleKit.LaserBarrier(_ctx.Hazards, new Vector3(7f, 5.4f, 193.2f), null, 3.4f, 3, 1.8f, 2.4f, 1.2f);
            var v3 = PuzzleKit.MovingPlatform(_ctx.Puzzles, new Vector3(7f, 5.4f, 198.3f), null, new[] { Vector3.zero, new Vector3(0f, 2.9f, 0f) }, new Vector3(3.8f, 0.4f, 4f), 1.6f, 2.6f, PlatformLoop.PingPong);
            Floor(g, new Vector3(5.75f, RoofY, 202.45f), new Vector3(6.4f, 0.4f, 4.2f), MatKey.Grate);
            EnvKit.Railing(g, new Vector3(8.95f, RoofY, 200.4f), new Vector3(8.95f, RoofY, 204.5f));
            EnvKit.Railing(g, new Vector3(2.6f, RoofY, 204.55f), new Vector3(8.95f, RoofY, 204.55f));
            _ctx.Mark("S5.V1", v1.gameObject); _ctx.Mark("S5.V2", v2.gameObject); _ctx.Mark("S5.V3", v3.gameObject);
            _ctx.Mark("S5.GL1", gl1.gameObject); _ctx.Mark("S5.GL2", gl2.gameObject);
            _ctx.MarkPoint("S5.M0", new Vector3(6.6f, PitY, 169.8f));
            _ctx.MarkPoint("S5.M0Dock", new Vector3(7f, PitY, 172.6f));
            _ctx.MarkPoint("S5.M1Dock", new Vector3(7f, 1.4f, 179.4f));
            _ctx.MarkPoint("S5.M1Safe", new Vector3(7f, 1.4f, 184.6f));
            _ctx.MarkPoint("S5.M1Wait", new Vector3(7f, 1.4f, 180.6f));
            _ctx.MarkPoint("S5.M2Dock", new Vector3(7f, 5.4f, 191.4f));
            _ctx.MarkPoint("S5.M2Safe", new Vector3(7f, 5.4f, 195.2f));
            _ctx.MarkPoint("S5.M3", new Vector3(6f, RoofY, 202.4f));

            // dressing
            PostSign(g, new Vector3(8.9f, PitY + 1.8f, 168f), Yaw(-90f), "MAINTENANCE SHAFT\nAUTHORIZED COUNTERWEIGHTS ONLY", 3.4f, 0.9f, SignStyle.Danger, PitY, true);
            Sign(g, new Vector3(5.6f, RoofY + 1.4f, 204.48f), FaceSouth, "<  ROOF HATCH", 2.2f, 0.6f, SignStyle.Arrow);   // on the north railing, seen from the top lift
            PostSign(t, new Vector3(-6.5f, UpperY + 1.6f, 197.5f), FaceSouth, "ESCAPE POD: MAX 200 KG.\nCHOOSE WISELY.", 3.6f, 1.0f, SignStyle.Danger, UpperY, true);
            PostSign(t, new Vector3(4.2f, UpperY + 1.2f, 181f), Yaw(-90f), "MAINTENANCE SHAFT  >\n(NO RAILING. NO REFUNDS.)", 2.8f, 0.9f, SignStyle.Arrow, UpperY);
            Beacon(t, new Vector3(-9.4f, UpperY, 199f), true);
            Beacon(t, new Vector3(3.9f, UpperY, 196f));
            Beacon(g, new Vector3(8.6f, 5.4f, 190.6f));
            Lamp(t, new Vector3(-2.8f, UpperY + 4.2f, 206.1f), FaceSouth, Amber, true, 5f, 0.4f, 2.6f);
            EnvKit.Decor.CrateStack(t, new Vector3(-8.6f, UpperY, 192f), Yaw(30f), 3, 12);
            EnvKit.Decor.BrokenBeam(t, new Vector3(-9.2f, UpperY, 180f), Yaw(10f), 3f);
            EnvKit.Decor.Debris(t, new Vector3(-6f, UpperY, 194f), 1.2f, 10, 51);
            EnvKit.Poster(t, new Vector3(-9.7f, UpperY + 1.6f, 184f), Face(Yaw(90f)), "END OF SHIFT BONUS", "ONE (1) SEAT ON A POD");
            for (int s = -1; s <= 1; s += 2)   // free-standing at the deck edge: two legs behind the poster
                Kit.BoxVisual(t, "PosterLeg", new Vector3(-9.78f, UpperY + 0.42f, 184f + s * 0.42f), new Vector3(0.08f, 0.84f, 0.08f), MatKey.MetalDark, 0.01f);

            _ctx.Tutorial(new Vector3(-2.8f, UpperY + 1.5f, 192f), new Vector3(14f, 4f, 6f), "l5_pod", "ESCAPE POD",
                "MAX 200 KG. Together you weigh more than that. Two can sit inside, the third rides on the ROOF via the maintenance shaft... or you press {Interact} on the console and leave someone behind.", null, true);
            _ctx.Hint(new Vector3(-1f, UpperY + 2f, 196f), new Vector3(18f, 8f, 18f),
                "Two interns in the pod (any two fit under 200 kg). The third climbs the maintenance shaft lifts beside the deck to the pod roof - the roof counts as inside, but not on the scale.",
                "The scale only weighs the floor.");
        }

        // ================================================================== world: void, backdrop, kill zone
        void BuildWorld()
        {
            PuzzleKit.KillZone(_ctx.Hazards, new Vector3(0f, -12f, 100f), null, new Vector3(260f, 30f, 420f), KillZoneType.Void, null, "fell into the meltdown");
            EnvKit.VoidBackdrop(_ctx.Decor, _ctx.Theme, new Bounds(new Vector3(0f, 0f, 100f), new Vector3(40f, 20f, 220f)), 55);
        }
